Func<dynamic, Context, CancellationToken, Task> HandleAsync = async (view, ctx, ct) =>
{
    if (view.Card is not Orc.Cards.Card discarded || view.Source is not Orc.Cards.Card source || view.Host is not Orc.Cards.Card self)
    {
        return;
    }

    if (object.ReferenceEquals(source, self))
    {
        return;
    }

    var sourceOwner = (source as Orc.Game.Cards.CardBase)?.Owner;
    var selfOwner = (self as Orc.Game.Cards.CardBase)?.Owner;
    if (sourceOwner is null || selfOwner is null || object.ReferenceEquals(sourceOwner, selfOwner))
    {
        return;
    }

    var runtime = Orc.Game.Effects.EffectRuntime.ResolveFor(self);
    if (runtime is null)
    {
        return;
    }

    await runtime.FetchFromDeckAsync(self, ct, self);
};
